def svg(i,tone='ink',inline=False):
 size=48 if i['family']=='editorial' else 24
 attr='aria-hidden="true" focusable="false"' if inline else f'role="img" aria-label="{html.escape(i["name"])}"'
 accent=f'<g class="accent" fill="var(--icon-accent, #963F28)" stroke="none" opacity=".18">{i["accent"]}</g>' if tone=='earth' and i['accent'] else ''
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {size} {size}" width="{size}" height="{size}" {attr} class="kl-icon" fill="none" stroke="currentColor" stroke-width="{1.8 if size==48 else 1.6}" stroke-linecap="round" stroke-linejoin="round">{accent}{i["paths"]}</svg>'
for i in icons:
 for tone in ['ink','earth']:
  d=A/tone;d.mkdir(exist_ok=True);(d/(i['id']+'.svg')).write_text(svg(i,tone))
manifest={'version':'0.2.0','status':'Option A single-colour direction approved; individual motif placement remains under review','approved_treatment':'ink','approval_quote':'I like the icon with the single-color option A','direction':'Earth & voice','credit':'Creative direction: Ahimanikya Satapathy. Original SVG construction: AI-assisted design study for Kabita Live.','rules':{'utility_viewbox':24,'editorial_viewbox':48,'utility_stroke':1.6,'editorial_stroke':1.8,'utility_sizes':[20,24],'editorial_sizes':[36,48,72],'touch_target_min':44,'no_auto_publication':True,'no_third_party_paths_copied':True},'icons':[{k:v for k,v in i.items() if k not in ['paths','accent']} for i in icons]}
(A/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
(A/'README.txt').write_text('KABITA LIVE — EARTH & VOICE / candidate v0.1\n26 original SVG symbols: 14 editorial motifs and 12 utility icons.\nOption A single-colour ink is the approved direction. Earth is a historical comparison, not the selected treatment.\nNo other project logo or third-party SVG geometry was copied.\nUse inline SVG for currentColor inheritance. With <img>, set alt="" beside visible text; standalone images need meaningful alt.\nDecorative inline SVG: aria-hidden="true", focusable="false". Action accessible names belong on the button/link.\nEditorial minimum 36px; utility 20–24px, in at least 44px targets. Keep familiar action labels.\nOne motif per section introduction; never one beside every verse, paragraph or menu item.\nPipili Chandua artwork stays reserved for future use. No sacred emblem used as a generic control.\nCultural references are interpretive; labels do not certify a craft pattern, botanical species or topographic likeness.\nSingle-colour treatment approved; review motif placement before site-wide adoption. No external library integration or public licence decision implied.\n')
# Reusable symbol sprite uses the same optical masters.
