(A/'sprite.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg">'+''.join(symbols)+'</svg>')
base=(S/'index.html').read_text();header=re.search(r'<header.*?</header>',base,re.S).group();footer=re.search(r'<footer.*?</footer>',base,re.S).group()
def page(title,body,extra=''):
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · Kabita Live</title><link rel="stylesheet" href="assets/style.css?revision=38"><link rel="stylesheet" href="assets/icon-study.css"><script defer src="assets/app.js"></script>{extra}</head><body class="journal-paper cotton-paper"><a class="skip" href="#main">Skip to content</a>{header}<main id="main" class="wrap atelier" tabindex="-1">{body}</main>{footer}</body></html>'
intro='''<nav class="study-links" aria-label="Study navigation"><a href="design-system-review.html#ornament">Design review desk</a><a href="literary-study.html">Literary site study</a></nav><section class="atelier-opening"><div><span class="eyebrow">Earth & voice · Option A selected</span><h1>Small marks.<br>A sense of home.</h1><p class="lede">A leaf that remembers. A thread that becomes a line. A little rain, held in the margin.</p><p>Original symbols for Kabita Live’s poetic world. Familiar controls stay clear; cultural motifs give selected stories a quiet sense of place.</p></div><div class="opening-marks" aria-hidden="true">'''+svg(icons[0],'ink',True)+svg(icons[2],'ink',True)+svg(icons[7],'ink',True)+'''</div></section>
<section aria-labelledby="directions"><span class="eyebrow">01 · Choose the character</span><h2 id="directions">One colour. A quiet character.</h2><div class="direction-pair"><article><div class="direction-art">'''+''.join(svg(icons[n],'ink',True) for n in [1,2,6])+'''</div><h3>A · Quiet ink — selected</h3><p>Approved direction. A single colour and soft line endings. Closest to a small drawing in a book’s margin.</p></article><article><div class="direction-art earth">'''+''.join(svg(icons[n],'earth',True) for n in [1,2,6])+'''</div><h3>B · Earth accent — earlier study</h3><p>Preserved for comparison. The selected icon family uses one colour without this laterite wash.</p></article></div></section>
<section aria-labelledby="library"><span class="eyebrow">02 · The collection</span><h2 id="library">Objects, places, quiet gestures.</h2><p>14 editorial motifs and 12 familiar controls. Every motif has a story and a suggested home.</p><div class="study-controls"><label>Find a symbol<input id="icon-search" type="search" placeholder="Try cloth, rain or archive"></label><label>Family<select id="icon-family"><option value="all">All symbols</option><option value="editorial">Editorial motifs</option><option value="utility">Everyday controls</option></select></label><label>Treatment<select id="icon-tone"><option value="ink">Quiet ink</option><option value="earth">Earth accent · earlier study</option></select></label><label>Editorial size<select id="icon-size"><option value="48">48px</option><option value="36">36px · minimum</option><option value="72">72px</option></select></label><label class="night-option"><input id="icon-night" type="checkbox">Dark-paper proof</label></div><p id="icon-count" role="status">26 symbols</p><div class="icon-grid" id="icon-grid">'''
cards=[]
for i in icons:
 cards.append(f'<article class="icon-card" data-family="{i["family"]}" data-search="{html.escape((i["name"]+" "+i["id"]+" "+i["story"]+" "+i["use"]).lower())}"><div class="icon-proof"><span class="ink-proof">{svg(i,"ink",True)}</span><span class="earth-proof">{svg(i,"earth",True)}</span><span class="family-label">{i["family"]}</span></div><h3>{i["name"]}</h3><p>{i["story"]}</p><p class="use-note"><strong>Use:</strong> {i["use"]}</p><a class="svg-download" href="assets/icons/earth-voice-v1/ink/{i["id"]}.svg" download>Download SVG<span class="sr-only">: {i["name"]}</span></a></article>')
body=intro+''.join(cards)+'''</div><p id="icon-empty" hidden>No matching symbol. Try “rain”, “cloth” or choose All symbols.</p></section>
<section aria-labelledby="in-place"><span class="eyebrow">03 · In the journal</span><h2 id="in-place">A flavour, not a pattern everywhere.</h2><div class="context-pair"><article class="context-example">'''+svg(icons[3],'ink',True)+'''<p class="eyebrow">A proposed editorial collection</p><h3>The things we carry home.</h3><p>Cloth, courtyards and the everyday objects that keep a life close.</p><a href="poems.html" class="text-link">Explore poems</a></article><article class="context-example"><p class="eyebrow">Reader tools · appearance specimen</p><h3>Let the poem lead.</h3><p>Small familiar shapes sit beside words. The artwork never interrupts a stanza.</p><div class="sample-tools"><span>'''+svg(icons[16],'ink',True)+''' Share</span><span>'''+svg(icons[17],'ink',True)+''' Save poem</span><span>'''+svg(icons[18],'ink',True)+''' Listen</span></div><p class="muted">These are visual examples, not active reading controls.</p></article></div></section>
<section aria-labelledby="rules"><span class="eyebrow">04 · A small discipline</span><h2 id="rules">Give each mark a reason to be here.</h2><div class="rules-grid"><article><h3>Keep the words</h3><p>Labels carry meaning. Never make a visitor guess that a conch means audio or a boat means sharing. Social platforms keep their recognisable names.</p></article><article><h3>Let motifs breathe</h3><p>One motif at a collection or editorial opening. Avoid decorative symbols beside every paragraph, poem or navigation item. Do not combine a motif with another divider in the same spot.</p></article><article><h3>Respect the reference</h3><p>These drawings are interpretations, not certified craft patterns. Pipili Chandua stays reserved. People such as Fakir Mohan belong in sourced portraits and stories, not generic interface glyphs.</p></article><article><h3>Proof the small size</h3><p>Editorial motifs begin at 36px. Controls use a separate 24-unit drawing at 20–24px, inside a target of at least 44px. Focus, contrast and labels remain visible.</p></article></div></section>
<section class="review-close"><h2>Selected: Option A, single-colour ink.</h2><p><strong>Quiet ink is the approved treatment.</strong> Each icon uses a single colour. Next, choose which editorial motifs belong in the journal and where they add meaning.</p><p>No icons have been applied across the reader pages. The current logo, separator, colours and typefaces remain approved references.</p><a class="text-link" href="assets/icons/earth-voice-v1/manifest.json" download>Download the asset register</a> · <a class="text-link" href="literary-study.html">Read the research &amp; sources</a></section>'''
(S/'icon-atelier.html').write_text(page('Small marks, a sense of home',body,'<script defer src="assets/icon-study.js"></script>'))
# The research is deliberately concise and source-linked; observations and proposals are separate.
rows=[
('Poetry Foundation','https://www.poetryfoundation.org/topics-themes','Themes connect poems, essays and other media; topic discovery extends beyond author names.','Add a small, editor-curated set of themes near poem results: home, longing, rain, labour, journeys.','Keep themes shallow and useful. Avoid a large taxonomy before the archive is consistently tagged.'),
('Poets.org','https://poets.org/poems','Search supports occasion, theme, form, title/text and poet. Its homepage gives a recurring poem a clear place.','Retain “A poem to begin with.” Make writer, title and first-line search work across the three scripts.','A monthly magazine can feature a rotating selection without promising daily publication.'),
('Rekhta','https://www.rekhta.org/','Couplets, poets, topic tags, sharing and downloads are connected; multiple script renderings help discovery.','Keep script choices and sharing beside the poem. Quote cards should carry title, poet and original URL.','Language, translation and transliteration are different. Do not imply every poem has all three, or add busy carousels.'),
('The Paris Review','https://www.theparisreview.org/poetry','Poetry can be browsed by name and decade, while the wider journal distinguishes issue content, interviews and daily work.','Keep an issue-led archive and writer contribution lists. Add clear breadcrumbs from poem to issue to archive.','Do not import its advertising space, subscription complexity or dense secondary navigation into this small journal.'),
('Asymptote','https://www.asymptotejournal.com/','Issue entries put translators and source languages beside the writing; each issue also credits its visual artist.','Show the translator next to the poet whenever applicable. Link editions to their cover narrative and common art credit record.','Central credits must not hide authorship. Preserve original line breaks; avoid blanket automatic translation.'),
('Poetry Archive','https://poetryarchive.org/','Voice recordings, poet pages, collections and search make listening a major discovery path.','Offer a labelled “Listen” only where a recording exists, with the performer and text nearby.','Never autoplay. Audio rights, transcripts and actual recordings must exist before enabling the feature.')]
table=''.join(f'<tr><th scope="row"><a href="{url}" target="_blank" rel="noopener">{name}</a></th><td>{obs}</td><td>{proposal}</td><td>{caution}</td></tr>' for name,url,obs,proposal,caution in rows)
research='''<nav class="study-links" aria-label="Study navigation"><a href="icon-atelier.html">Open the icon atelier</a><a href="design-system-review.html">Design review desk</a></nav><section class="atelier-opening research-opening"><div><span class="eyebrow">Research note · 29 September 2026 · Proposals for review</span><h1>Learn from the shelves.<br>Keep our own voice.</h1><p class="lede">The best lesson is a reading journey: discover a poem, meet its writer, find another voice, return to the journal.</p><p>Six established poetry and literary destinations, studied for useful patterns. This is a qualitative benchmark, not a verified ranking of today’s most visited sites. Poetry Archive reports five million visitors a year on its own homepage; that is self-reported, not an independent comparison.</p></div></section>
<section><h2>What we can learn.</h2><p>Observations describe the referenced pages. Recommendations are our design judgments for Kabita Live.</p><div class="research-table"><table><caption>Six references and their practical implications</caption><thead><tr><th>Reference</th><th>Observed pattern</th><th>For Kabita Live</th><th>Keep the scope clear</th></tr></thead><tbody>'''+table+'''</tbody></table></div></section>
<section><h2>What Utkal teaches us.</h2><div class="context-pair"><article><h3>Blueprint: a memory for decisions</h3><p>The supplied <a href="https://github.com/ahimanikya/utkal-blueprint">Utkal Blueprint</a> contains an operating model, source records, decisions and approval boundaries. The inspected main-branch tree contains no icon library. Borrow its traceability: each icon records its meaning, use, source, version and approval state.</p><p>Following the user’s subsequent instruction, Kabita Live now adopts the Blueprint locally, with its own charter and records. No template roles were activated.</p></article><article><h3>Utkal Project: a family of masters</h3><p>The related <a href="https://github.com/ahimanikya/utkal-project/blob/main/kb/reference/brand-vector-03.md">Utkal Project vector study</a> has coordinated full-size and small-size symbols, colour and reverse variants, and outlined wordmarks. Those are useful production habits. Its book-and-boat emblem remains Utkal’s own.</p><p>Use Kabita Live’s existing palette and leaf-and-stream identity. Reuse the discipline, not another project’s logo or its slightly different colour values.</p></article></div><p class="source-note">Repository inspection: Utkal Project commit 5ce3e2494488f7d5e273a035274108dc8b8861ae. Read-only study; no remote files or operating rules changed. The user clarified that Kabita Live should first become a Blueprint project and build its own reusable icon list.</p></section>
<section><h2>A practical order for the next reviews.</h2><ol class="priorities"><li><strong>Reading and discovery.</strong> Audit title/poet/first-line search, language filters, issue breadcrumbs and three-script line wrapping. These matter more than adding more decoration.</li><li><strong>Writer continuity.</strong> Check every writer profile’s contribution list, language, issue and source link. Give the reader a clear next poem.</li><li><strong>Share with authorship intact.</strong> Keep title, poet, original link and any translator attached. Display a quiet share action; report copy success only when it succeeds.</li><li><strong>Small marks.</strong> Review the new icon family in the atelier. Apply a few approved motifs to editorial collections and familiar controls to actions.</li><li><strong>Optional future layers.</strong> Curated themes, saved poems and recordings require a separate content and behaviour review. No new account, audio library or publishing workflow is implied.</li></ol></section>
<section><h2>The icon language.</h2><p>“ମାଟିର ମହକ · ମନର ସ୍ୱର” becomes a drawing discipline: open contours, a little asymmetry, warm paper and a single ink colour, selected by the user as Option A. The 48-unit editorial drawings can suggest a manuscript, cloth, leaf, lagoon or hill. The 24-unit utility drawings preserve recognisable actions.</p><p>Proposed use: one editorial motif at a collection opening, modest utility symbols beside labels, and no new ornament on the masthead or footer. No animated motifs. The existing logo and header separator retain their role.</p><a class="text-link" href="icon-atelier.html">Explore all 26 symbols</a></section>
<details class="study-sources"><summary>Sources, cultural references &amp; limits</summary><p>The six linked pages above are the primary literary references. Supporting pages: <a href="https://poets.org/">Poets.org homepage</a>, <a href="https://www.theparisreview.org/">The Paris Review homepage</a>, <a href="https://www.poetryfoundation.org/topics">Poetry Foundation topic index</a>. Direct visual inspection covered Poets.org, The Paris Review, Rekhta and Asymptote. Poetry Foundation evidence came from indexed official pages after a direct fetch was blocked. Poetry Archive was inspected through its official page text. No comparative traffic dataset or complete accessibility audit of those sites was obtained.</p><p>Cultural grounding: <a href="https://odishatourism.gov.in/content/tourism/en/discover/attractions/arts-crafts/pipili.html">Odisha Tourism: Pipili</a>; <a href="https://apps.odishatourism.gov.in/tour/odisha-textile-tour">Odisha textile tour</a>; <a href="https://apps.odishatourism.gov.in/forest-wildlife">Forests and wildlife</a>; <a href="https://odishatourism.gov.in/content/tourism/en/experience/activities/bird-watching.html">Bird watching</a>; <a href="https://apps.odishatourism.gov.in/tour/odisha-temple-tour">Raghurajpur and palm-leaf craft</a>. Puri gamucha and kendu woodland came from the user’s creative brief. Symbol shapes are original interpretations, not documentary reproductions or assertions of exclusive Odisha ownership. Pipili artwork is preserved for future use.</p><p>Creative direction: Ahimanikya Satapathy. Research, SVG construction and study implementation prepared with AI assistance. No paths were copied from the reference sites or Utkal. These candidate assets remain local and unapproved for site-wide adoption. Keep attribution in the common colophon if adopted; retain this asset register with exports.</p></details>'''
(S/'literary-study.html').write_text(page('Literary research and icon direction',research))
(R/'revision-40-literary-icons/icon-catalogue.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
print('Generated',len(icons),'icons in two treatments; atelier, research and register.')
